{
  "apiVersion": 1,
  "type": "component.detail.props",
  "package": "@astryxdesign/core",
  "data": [
    {
      "name": "mode",
      "type": "'single' | 'range'",
      "description": "Selection mode.",
      "default": "'single'"
    },
    {
      "name": "value",
      "type": "ISODateString | DateRange | null",
      "description": "Controlled selected value. Use null for no selection; omit value or pass undefined for uncontrolled mode."
    },
    {
      "name": "defaultValue",
      "type": "ISODateString | DateRange",
      "description": "Uncontrolled default value."
    },
    {
      "name": "onChange",
      "type": "Function",
      "description": "Selection callback."
    },
    {
      "name": "numberOfMonths",
      "type": "1 | 2",
      "description": "Number of months to display.",
      "default": "1"
    },
    {
      "name": "min",
      "type": "ISODateString",
      "description": "Minimum selectable date."
    },
    {
      "name": "max",
      "type": "ISODateString",
      "description": "Maximum selectable date."
    },
    {
      "name": "dateConstraints",
      "type": "Array<(date: Date) => boolean>",
      "description": "Custom constraint functions."
    },
    {
      "name": "maxRangeSpan",
      "type": "number",
      "description": "Range mode: max days a range may span, both endpoints counted (7 = a 7-day window). Caps the window from the picked start; before a start is picked every day stays selectable."
    },
    {
      "name": "minRangeSpan",
      "type": "number",
      "description": "Range mode: min days a range must span, both endpoints counted (2 forbids a single-day range). Clicking the start again commits a one-day range when allowed, or cancels the in-progress selection when the minimum is longer. Default 1."
    },
    {
      "name": "focusDate",
      "type": "ISODateString",
      "description": "Controlled visible month. Unset, the calendar opens on the selected date, else on today clamped into the min/max window."
    },
    {
      "name": "onFocusDateChange",
      "type": "(focusDate: ISODateString) => void",
      "description": "Navigation callback."
    },
    {
      "name": "handleRef",
      "type": "React.Ref<CalendarHandle>",
      "description": "Imperative handle for calendar navigation, including navigateTo()."
    },
    {
      "name": "hasOutsideDays",
      "type": "boolean",
      "description": "Show days from adjacent months.",
      "default": "true"
    },
    {
      "name": "hasWeekNumbers",
      "type": "boolean",
      "description": "Show ISO 8601 week numbers. They are ISO 8601 week numbers in every calendar system.",
      "default": "false"
    },
    {
      "name": "hasVariableRowCount",
      "type": "boolean",
      "description": "Give each month only the rows it needs. The default fixed 6-row grid keeps the same height from month to month; a variable row count trades that fixed height for a more compact grid.",
      "default": "false"
    },
    {
      "name": "weekStartsOn",
      "type": "0 | 1 | 2 | 3 | 4 | 5 | 6 | 'sun' | 'mon' | 'tue' | 'wed' | 'thu' | 'fri' | 'sat'",
      "description": "First day of week. Accepts a number (0=Sunday) or a three-letter day name (e.g. \"mon\").",
      "default": "0"
    },
    {
      "name": "calendar",
      "type": "'gregory' | 'iso8601' | 'buddhist' | 'roc' | 'japanese' | 'persian' | 'indian' | 'hebrew' | 'chinese' | 'dangi' | 'coptic' | 'ethiopic' | 'ethioaa' | 'islamic-civil' | 'islamic-tbla' | 'islamic-umalqura'",
      "description": "Calendar system the grid shows, such as 'persian', 'hebrew', or 'islamic-umalqura'. It sets the months, their names, and month and year navigation. value, min, max, focusDate, and every callback stay Gregorian ISO dates. Calendars other than gregory, iso8601, buddhist, roc, and japanese need Temporal; where the runtime lacks it, load a polyfill such as temporal-polyfill/full/global on the server and in the browser, or the grid shows Gregorian months. Month starts in the Chinese and Dangi calendars come from the runtime's Temporal, and some polyfills start a few months one day apart from native Temporal; when server and browser markup must match, use one implementation on both sides, such as installImplementation() from temporal-polyfill/full/shim, which replaces a native Temporal.",
      "default": "the InternationalizationProvider calendar, else gregory"
    }
  ],
  "meta": {
    "answeredBy": {
      "cli": "0.7.12",
      "core": "0.7.12",
      "copy": "starting"
    }
  }
}
